mapper.select:
SELECT 
FROM user_problem_note
WHERE user_id = #{userId}
  AND problem_slug = #{problemSlug}

UPDATE user_problem_note
SET outline_json = #{outlineJson, typeHandler=org.congcong.algomentor.agent.persistence.postgres.json.JsonbTypeHandler},
    revision = revision + 1,
    updated_at = #{now}
WHERE user_id = #{userId}
  AND problem_slug = #{problemSlug}
  AND revision = #{expectedRevision}
RETURNING

UPDATE user_problem_note
SET note_markdown = #{summaryMarkdown},
    coach_summary_revision = coach_summary_revision + 1,
    coach_summary_updated_at = #{now}
WHERE user_id = #{userId}
  AND problem_slug = #{problemSlug}
  AND coach_summary_revision = #{expectedCoachSummaryRevision}
RETURNING

mapper.delete:
DELETE FROM user_problem_note
WHERE user_id = #{userId}
  AND problem_slug = #{problemSlug}
